(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key='nilia-demo-v1';
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',alunos:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',turmas:'M3 21h18 M5 21V7l7-4 7 4v14 M9 21v-5h6v5 M9 9h.01 M15 9h.01 M9 12h.01 M15 12h.01',notas:'M9 5H5v16h14V5h-4 M9 3h6v4H9z M8 12h8 M8 16h5',presencas:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M8 15l3 3 5-5',propinas:'M3 5h18v14H3z M3 9h18 M7 15h4 M16 15h1',horarios:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',comunicados:'M3 10v4h4l11 5V5L7 10H3 M7 14l2 7h3l-2-6',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M18 6L6 18',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',book:'M12 6C9 3 5 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2 M12 6v15'};
const icon=(name)=>`<svg class="uiIcon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.dashboard).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;
const seed=()=>({students:['Amélia','Bruno','Carla','Daniel','Eva','Filipe','Graça','Hugo'].map((n,i)=>({id:i+1,name:n+' Demo',class:i<4?'8.ª A':i<6?'9.ª A':'5.ª A',grades:{Português:12+i%6,Matemática:11+i%7,Inglês:13+i%5},paid:i%3!==0})),attendance:{},notices:[{title:'Encontro com os encarregados de educação',text:'Exemplo de comunicado: reunião de acompanhamento do primeiro trimestre.',date:'12/02/2027'},{title:'Semana das artes e do desporto',text:'Exemplo de actividade escolar para apresentar o mural de comunicações.',date:'08/02/2027'}]});
let data;try{data=JSON.parse(localStorage.getItem(key))}catch{}if(!data?.students)data=seed();let role='secretaria',route='dashboard',filters={class:'',subject:'Português',date:'2027-02-15',search:'',fee:''};
const modules={dashboard:['Visão geral','Um olhar sobre a vida académica.'],alunos:['Alunos','Consulte e explore os registos de demonstração.'],turmas:['Turmas','Organização das turmas e acompanhamento dos alunos.'],notas:['Avaliações','Pautas de demonstração · Escala de 0 a 20 valores.'],presencas:['Presenças','Registo diário de assiduidade.'],propinas:['Propinas','Valores ilustrativos, sem pagamentos reais.'],horarios:['Horários','Uma semana de aprendizagem, organizada.'],comunicados:['Comunicados','Informações para a comunidade escolar.']};
const permitted=()=>role==='secretaria'?Object.keys(modules):role==='professor'?['dashboard','turmas','alunos','notas','presencas','horarios','comunicados']:['dashboard','notas','presencas','propinas','horarios','comunicados'];
const students=()=>data.students.filter(s=>role!=='familia'||s.id===1),classes=()=>[...new Set(students().map(s=>s.class))],filtered=()=>students().filter(s=>(!filters.class||s.class===filters.class)&&s.name.toLowerCase().includes(filters.search.toLowerCase()));
function save(){try{localStorage.setItem(key,JSON.stringify(data))}catch{toast('Alteração guardada apenas nesta sessão.')} }
let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const money=n=>n.toLocaleString('pt-MZ')+' MT',badge=(t,c='good')=>`<span class="status ${c}">${t}</span>`,person=s=>`<div class="person"><span class="initials">${esc(s.name[0])}D</span><span>${esc(s.name)}<small>N2027-${String(s.id).padStart(3,'0')}</small></span></div>`,btn=(t,a,secondary=false)=>`<button class="btn ${secondary?'secondary':''}" data-action="${a}">${t}</button>`;
const classSelect=()=>`<label>Turma<select data-filter="class"><option value="">Todas as turmas</option>${classes().map(c=>`<option ${filters.class===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;
const table=(heads,rows)=>{let cell=0;rows=rows.replace(/<tr>/g,()=>{cell=0;return '<tr>'}).replace(/<td(?![^>]*colspan)([^>]*)>/g,(_,attrs)=>`<td${attrs} data-label="${esc(heads[cell++%heads.length])}">`);return `<div class="tableWrap ${heads[0]==='Hora'?'timetable':''}" tabindex="0" aria-label="Tabela com deslocação horizontal"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}">Nenhum resultado para estes filtros.</td></tr>`}</tbody></table></div>`};
const panel=(title,body,action='')=>`<section class="panel portalReveal"><div class="panelTop"><h2>${title}</h2>${action}</div>${body}</section>`;
function drawer(open){$('.main').inert=open;$('#mobileNav').inert=open;document.body.classList.toggle('drawerOpen',open);$('#sidebarClose').hidden=!open;$('#sidebar').classList.toggle('open',open);$('#mobileBackdrop').hidden=!open;$('#menu').setAttribute('aria-expanded',open);$('#menu').setAttribute('aria-label',open?'Fechar módulos':'Abrir módulos');if(open)$('#sidebarClose').focus();else if(matchMedia('(max-width:850px)').matches)$('#menu').focus()}
function modal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal()}
function renderMobileNav(){const items=['dashboard','notas','horarios'];$('#mobileNav').innerHTML=items.map(m=>`<a href="#${m}" ${route===m?'aria-current="page"':''}>${icon(m)}<span>${m==='dashboard'?'Início':modules[m][0]}</span></a>`).join('')+`<button type="button" data-action="openMenu">${icon('menu')}<span>Mais</span></button>`}
function dashboard(){let ss=students(),paid=ss.filter(s=>s.paid).length;return `<section class="dashboardLead portalReveal"><div><span class="leadLabel">INSTITUTO NÍLIA / ÁREA ACADÉMICA</span><h2>${role==='familia'?'O percurso da Amélia.':role==='professor'?'Ensinar. Acompanhar. Inspirar.':'A escola, mais próxima.'}</h2><p>${role==='familia'?'Amélia Demo · 8.ª A · Acompanhe cada etapa da aprendizagem.':role==='professor'?'Avaliações, presenças e turmas. O essencial para acompanhar os seus alunos.':'Uma visão clara dos alunos, das turmas e da vida escolar.'}</p><button class="btn leadBtn" data-action="goto:${role==='secretaria'?'alunos':'notas'}">${role==='secretaria'?'Consultar alunos':'Consultar avaliações'} ${icon('arrow')}</button></div><div class="leadEmblem" aria-hidden="true"><img src="assets/logotipo-nilia.jpg" alt=""><span>APRENDER<br>PARA CRESCER</span></div></section><div class="stats">${[[ss.length,role==='familia'?'Educando associado':'Alunos','Registos de demonstração','alunos'],[classes().length,'Turmas','Ano lectivo de 2027','turmas'],[Number((ss.reduce((a,s)=>a+s.grades.Português,0)/ss.length).toFixed(1)),'Média em Português','Escala de 0 a 20','notas'],[role==='professor'?'3':money(paid*2500),role==='professor'?'Disciplinas':'Propinas regularizadas',role==='professor'?'Pautas de exemplo':'Valores fictícios','propinas']].map(x=>`<div class="stat portalReveal"><div class="statLabel">${icon(x[3])}<span>${x[1]}</span></div><strong>${x[0]}</strong><small>${x[2]}</small></div>`).join('')}</div><section class="quickSection portalReveal"><h2>Acessos rápidos</h2><div class="quickGrid">${['notas','presencas','horarios','comunicados'].map(m=>`<a href="#${m}"><span class="quickIcon">${icon(m)}</span><span>${modules[m][0]}</span>${icon('arrow')}</a>`).join('')}</div></section><div class="grid2">${panel('Agenda da escola',`<div class="agenda"><div class="agendaItem"><div class="datebox"><strong>15</strong>FEV</div><div><b>Início da semana lectiva</b><p>Aulas e acompanhamento das turmas</p><small>07:30 · Turno da manhã</small></div></div><div class="agendaItem"><div class="datebox"><strong>19</strong>FEV</div><div><b>Actividades culturais</b><p>Música, expressão e trabalho de equipa</p><small>10:00 · Espaço escolar</small></div></div></div>`,`<button class="textBtn" data-action="goto:horarios">Ver horário ${icon('arrow')}</button>`)}${panel('Comunicados recentes',data.notices.slice(0,2).map(n=>`<article class="notice"><small>${esc(n.date)}</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></article>`).join(''),`<button class="textBtn" data-action="goto:comunicados">Ver todos ${icon('arrow')}</button>`)}</div><p class="hint demoHint">${icon('book')} Explore os perfis no topo. Os dados são fictícios e as alterações ficam apenas neste navegador.</p>`}
function render(){if(!permitted().includes(route))route='dashboard';$('#sideNav').innerHTML=permitted().map((m,i)=>`<a href="#${m}" ${m===route?'aria-current="page"':''}>${icon(m)}<span>${modules[m][0]}</span></a>`).join('');renderMobileNav();$('#pageTitle').textContent=modules[route][0];$('#pageDescription').textContent=modules[route][1];$('#eyebrow').textContent=role==='familia'?'Área da família · Amélia Demo':role==='professor'?'Área do professor':'Gestão escolar';let html='';
if(route==='dashboard')html=dashboard();
if(route==='alunos')html=panel('Directório de alunos',`<div class="toolbar"><label class="search">Procurar aluno<input data-filter="search" placeholder="Nome do aluno" value="${esc(filters.search)}"></label>${classSelect()}</div>`+table(['Aluno','Turma','Situação',''],filtered().map(s=>`<tr><td>${person(s)}</td><td>${esc(s.class)}</td><td>${badge('Activo')}</td><td><button class="textBtn" data-action="student:${s.id}">Ver ficha →</button></td></tr>`).join('')),role==='secretaria'?btn('+ Novo aluno','newStudent'):'');
if(route==='turmas')html=`<div class="classCards">${classes().map((c,i)=>`<article class="classCard portalReveal"><span class="eyebrow">Ensino geral · 2027</span><h2>${esc(c)}</h2><div class="big">${students().filter(s=>s.class===c).length}<small> alunos de exemplo</small></div><p>1.º trimestre · Turno da manhã</p><div class="bar"><i style="width:${45+i*15}%"></i></div><button class="textBtn" data-action="class:${esc(c)}">Consultar avaliações →</button></article>`).join('')}</div>`;
if(route==='notas')html=panel('Pauta de avaliações',`<div class="toolbar">${classSelect()}<label>Disciplina<select data-filter="subject">${['Português','Matemática','Inglês'].map(s=>`<option ${s===filters.subject?'selected':''}>${s}</option>`).join('')}</select></label></div>`+table(['Aluno','Turma','Nota / 20','Resultado'],filtered().map(s=>`<tr><td>${person(s)}</td><td>${esc(s.class)}</td><td>${role==='familia'?s.grades[filters.subject]:`<input type="number" min="0" max="20" step="0.1" data-grade="${s.id}" aria-label="Nota de ${esc(s.name)}" value="${s.grades[filters.subject]}">`}</td><td>${badge(s.grades[filters.subject]>=10?'Positiva':'A acompanhar',s.grades[filters.subject]>=10?'good':'warn')}</td></tr>`).join(''))+(role==='familia'?'':`<div class="inlineActions">${btn('Guardar avaliações','saveGrades')}<span class="hint">Gravação local de demonstração.</span></div>`));
if(route==='presencas')html=panel('Assiduidade',`<div class="toolbar">${classSelect()}<label>Data<input data-filter="date" type="date" value="${filters.date}"></label></div>`+table(['Aluno','Turma','Presença'],filtered().map(s=>{let val=data.attendance[filters.date]?.[s.id]||'Presente';return `<tr><td>${person(s)}</td><td>${esc(s.class)}</td><td>${role==='familia'?badge(val,val==='Falta'?'bad':'good'):`<select data-attendance="${s.id}" aria-label="Presença de ${esc(s.name)}">${['Presente','Falta','Justificada'].map(v=>`<option ${v===val?'selected':''}>${v}</option>`).join('')}</select>`}</td></tr>`}).join(''))+(role==='familia'?'':`<div class="inlineActions">${btn('Guardar presenças','saveAttendance')}</div>`));
if(route==='propinas')html=`<div class="stats"><div class="stat accent"><span>Mensalidade de exemplo</span><strong>2 500 MT</strong><small>Fevereiro de 2027 · Valor fictício</small></div><div class="stat"><span>Por regularizar</span><strong>${money(students().filter(s=>!s.paid).length*2500)}</strong><small>Simulação sem cobrança</small></div></div>`+panel('Situação das mensalidades',`<div class="toolbar">${classSelect()}<label>Situação<select data-filter="fee"><option value="">Todas</option><option value="paid" ${filters.fee==='paid'?'selected':''}>Regularizadas</option><option value="pending" ${filters.fee==='pending'?'selected':''}>Pendentes</option></select></label></div>`+table(['Aluno','Período','Valor','Situação',''],filtered().filter(s=>!filters.fee||(filters.fee==='paid'?s.paid:!s.paid)).map(s=>`<tr><td>${person(s)}</td><td>Fev. 2027</td><td>2 500 MT</td><td>${badge(s.paid?'Regularizada':'Pendente',s.paid?'good':'warn')}</td><td>${!s.paid&&role==='secretaria'?`<button class="textBtn" data-action="payment:${s.id}">Simular pagamento</button>`:'—'}</td></tr>`).join(''))+`<p class="hint">Não existe processamento de pagamentos nem emissão de recibos oficiais.</p>`);
if(route==='horarios')html=panel('Horário semanal',`<div class="toolbar">${classSelect()}</div><p class="hint">${esc(filters.class||classes()[0])} · Horário ilustrativo · Turno da manhã</p>`+table(['Hora','Segunda','Terça','Quarta','Quinta','Sexta'],['07:30 — 08:15','08:20 — 09:05','09:25 — 10:10','10:15 — 11:00'].map((t,i)=>`<tr><th scope="row">${t}</th>${Array.from({length:5},(_,j)=>`<td>${['Português','Matemática','Inglês','Ciências','Educação Física'][(i+j)%5]}</td>`).join('')}</tr>`).join('')));
if(route==='comunicados')html=panel('Mural de comunicações',data.notices.map(n=>`<article class="notice"><small>${esc(n.date)} · Comunidade escolar</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></article>`).join(''),role==='secretaria'?btn('+ Novo comunicado','newNotice'):'');
$('#screen').innerHTML=html;$('#screen').className='moduleEnter';animate();}
let observer;function animate(){observer?.disconnect();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.body.classList.add('motionEnabled');observer=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('inView',e.isIntersecting)),{threshold:.08});document.querySelectorAll('.portalReveal').forEach((e,i)=>{e.style.setProperty('--delay',Math.min(i%4*50,150)+'ms');observer.observe(e)})}
function action(a){let [cmd,id]=a.split(':');if(cmd==='openMenu'){drawer(true);return}if(cmd==='goto'){location.hash=id;return}if(cmd==='class'){filters.class=id;location.hash='notas';return}if(cmd==='student'){let s=data.students.find(s=>s.id===+id);modal('Ficha do aluno',`<div class="info">${person(s)}<div class="detailGrid"><p><small>Turma</small><b>${esc(s.class)}</b></p><p><small>Ano lectivo</small><b>2027 · Demonstração</b></p></div><h3>Avaliações de exemplo</h3>${Object.entries(s.grades).map(([k,v])=>`<div class="listRow"><span>${k}</span><b>${v} / 20</b></div>`).join('')}<p class="hint">Identidade inteiramente fictícia, sem dados pessoais reais.</p></div>`)}
if(cmd==='newStudent')modal('Novo aluno de demonstração',`<form id="studentForm" class="formGrid"><label class="full">Nome fictício<input name="name" required maxlength="60" placeholder="Ex.: Isabel Demo"></label><label>Turma<select name="class">${classes().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><p class="hint full">Utilize apenas nomes fictícios para apresentar o protótipo.</p><div class="full"><button class="btn">Guardar aluno</button></div></form>`);
if(cmd==='saveGrades'){let inputs=[...document.querySelectorAll('[data-grade]')];if(inputs.some(e=>e.value.trim()===''||!e.checkValidity())){toast('Preencha todas as notas entre 0 e 20.');inputs.find(e=>!e.value||!e.checkValidity())?.focus();return}inputs.forEach(e=>data.students.find(s=>s.id===+e.dataset.grade).grades[filters.subject]=+e.value);save();render();toast('Avaliações guardadas na demonstração.')}
if(cmd==='saveAttendance'){data.attendance[filters.date]??={};document.querySelectorAll('[data-attendance]').forEach(e=>data.attendance[filters.date][e.dataset.attendance]=e.value);save();toast('Presenças guardadas para '+filters.date+'.')}
if(cmd==='payment'){let s=data.students.find(s=>s.id===+id);modal('Simular regularização',`<div class="info"><p>Aluno: <b>${esc(s.name)}</b></p><p>Fevereiro de 2027 · <b>2 500 MT</b></p><p>Esta acção altera apenas o estado fictício neste navegador. Não movimenta dinheiro.</p>${btn('Confirmar simulação','confirmPayment:'+s.id)}</div>`)}
if(cmd==='confirmPayment'){data.students.find(s=>s.id===+id).paid=true;save();$('#modal').close();render();toast('Simulação concluída. Nenhum pagamento real foi efectuado.')}
if(cmd==='newNotice')modal('Novo comunicado de demonstração',`<form id="noticeForm" class="formGrid"><label class="full">Título<input name="title" required maxlength="100"></label><label class="full">Mensagem<textarea name="text" required maxlength="1000" rows="5"></textarea></label><p class="hint full">Fica apenas no mural deste navegador. Nenhuma mensagem será enviada.</p><div class="full"><button class="btn">Adicionar ao mural</button></div></form>`);
if(cmd==='reset')modal('Repor demonstração',`<div class="info"><p>Remove as alterações deste protótipo guardadas neste navegador e recupera os exemplos iniciais.</p>${btn('Repor exemplos','confirmReset')}</div>`);
if(cmd==='confirmReset'){data=seed();save();filters.class='';filters.search='';$('#modal').close();render();toast('Exemplos iniciais repostos.')}
}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)action(b.dataset.action)});
document.addEventListener('change',e=>{let f=e.target.dataset.filter;if(f){filters[f]=e.target.value;render()}});
document.addEventListener('submit',e=>{if(!['studentForm','noticeForm'].includes(e.target.id))return;e.preventDefault();let f=new FormData(e.target);if(e.target.id==='studentForm'){let name=f.get('name').trim();if(!name)return;data.students.push({id:Math.max(...data.students.map(s=>s.id))+1,name,class:f.get('class'),grades:{Português:0,Matemática:0,Inglês:0},paid:false});filters.search='';filters.class=''}else{if(!f.get('title').trim()||!f.get('text').trim())return;data.notices.unshift({title:f.get('title').trim(),text:f.get('text').trim(),date:new Date().toLocaleDateString('pt-PT')})}save();$('#modal').close();render();toast('Registo adicionado à demonstração.')});
$('#sideNav').addEventListener('click',e=>{if(e.target.closest('a'))drawer(false)});$('#sidebarClose').onclick=()=>drawer(false);$('#menu').innerHTML=icon('menu');$('#sidebarClose').innerHTML=icon('close');$('#closeModal').innerHTML=icon('close');$('#closeModal').onclick=()=>$('#modal').close();$('#menu').onclick=()=>drawer(!$('#sidebar').classList.contains('open'));$('#mobileBackdrop').onclick=()=>drawer(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')drawer(false);if(e.key==='Tab'&&$('#sidebar').classList.contains('open')){const items=[...$('#sidebar').querySelectorAll('a,button:not([hidden])')];const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('#reset').onclick=()=>action('reset');$('#role').onchange=e=>{role=e.target.value;filters.class='';filters.search='';route='dashboard';if(location.hash!=='#dashboard')location.hash='dashboard';else render()};window.addEventListener('hashchange',()=>{route=location.hash.slice(1);render();drawer(false);$('#content').focus()});route=location.hash.slice(1)||'dashboard';render();
})();
